const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const ctx = await browser.newContext();
  const page = await ctx.newPage();

  await page.goto('https://cafe.naver.com/teslakoreaclub', { waitUntil: 'domcontentloaded' });
  console.log('Cafe opened:', await page.title(), page.url());
  console.log('>> 이 창에서 네이버 로그인을 완료하세요. 로그인되면 자동으로 "통합장터"로 이동합니다.');

  // 로그인 대기: 로그인 버튼(gnb_my / login) 이 사라질 때까지 최대 5분
  const deadline = Date.now() + 5 * 60 * 1000;
  while (Date.now() < deadline) {
    const loggedIn = await page.evaluate(() => {
      const t = document.body.innerText || '';
      // 로그인 안내 문구가 없고, 로그아웃 링크가 있으면 로그인 상태로 간주
      const hasLogout = !!document.querySelector('a[href*="nid.naver.com/nidlogin.logout"], a#gnb_logout_button');
      return hasLogout || (!t.includes('로그인') && !t.includes('네이버 로그인'));
    }).catch(() => false);
    if (loggedIn) break;
    await page.waitForTimeout(3000);
  }
  console.log('로그인 감지 완료 (또는 시간 초과). 통합장터 메뉴 탐색 중...');

  // 좌측 메뉴는 cafe_main iframe 또는 메인 문서에 존재
  await page.goto('https://cafe.naver.com/teslakoreaclub', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2000);

  const targets = ['통합장터', '통합 장터', '장터'];
  let clicked = false;
  for (const frame of page.frames()) {
    for (const label of targets) {
      const link = frame.locator(`a:has-text("${label}")`).first();
      if (await link.count().catch(() => 0)) {
        try {
          await link.click({ timeout: 5000 });
          clicked = true;
          console.log(`"${label}" 클릭됨 in frame ${frame.url()}`);
          break;
        } catch (e) { /* try next */ }
      }
    }
    if (clicked) break;
  }

  if (!clicked) {
    console.log('통합장터 링크를 자동으로 찾지 못했습니다. 현재 프레임별 메뉴 링크 목록:');
    for (const frame of page.frames()) {
      const links = await frame.evaluate(() =>
        Array.from(document.querySelectorAll('a'))
          .map(a => (a.textContent || '').trim())
          .filter(x => x && x.length < 20)
      ).catch(() => []);
      if (links.length) console.log(`[${frame.url()}]`, links.slice(0, 60).join(' | '));
    }
  }

  console.log('완료. 브라우저는 열어둡니다.');
})();

