const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages()[0];

  await page.bringToFront();
  await page.goto('https://cafe.naver.com/teslakoreaclub', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(2500);

  // 로그인 상태 확인
  const bodyText = await page.evaluate(() => document.body.innerText.slice(0, 400));
  console.log('--- 메인 텍스트 일부 ---\n' + bodyText + '\n---');

  // 모든 프레임에서 메뉴 링크(장터 포함) 수집
  for (const frame of page.frames()) {
    const links = await frame.evaluate(() =>
      Array.from(document.querySelectorAll('a'))
        .map(a => ({ t: (a.textContent || '').trim(), href: a.href }))
        .filter(x => x.t && /장터|거치|악세|용품|판매|중고/.test(x.t))
    ).catch(() => []);
    if (links.length) {
      console.log(`[frame ${frame.url()}]`);
      links.forEach(l => console.log('  ', l.t, '=>', l.href));
    }
  }

  await page.screenshot({ path: 'shot-cafe-main.png', fullPage: false });
  console.log('saved shot-cafe-main.png');
})();

